const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
  ShadingType, PageBreak, ExternalHyperlink
} = require('docx');
const fs = require('fs');

// Brand palette
const NAVY = "0A1F44";
const GOLD = "B08D57";
const LIGHT = "F5F1EA";
const GREY = "4A4A4A";
const BORDER_GREY = "D9D9D9";

const border = { style: BorderStyle.SINGLE, size: 4, color: BORDER_GREY };
const borders = { top: border, bottom: border, left: border, right: border };

// Helpers
const p = (text, opts = {}) => new Paragraph({
  spacing: { before: 80, after: 80, ...(opts.spacing || {}) },
  alignment: opts.alignment,
  children: [new TextRun({ text, font: "Calibri", size: opts.size || 22, color: opts.color || GREY, bold: opts.bold })]
});

const pRuns = (runs, opts = {}) => new Paragraph({
  spacing: { before: 80, after: 80, ...(opts.spacing || {}) },
  alignment: opts.alignment,
  children: runs
});

const h1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 360, after: 180 },
  children: [new TextRun({ text, font: "Calibri", size: 40, bold: true, color: NAVY })]
});

const h2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 280, after: 140 },
  children: [new TextRun({ text, font: "Calibri", size: 30, bold: true, color: NAVY })]
});

const h3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3,
  spacing: { before: 200, after: 100 },
  children: [new TextRun({ text, font: "Calibri", size: 24, bold: true, color: GOLD })]
});

const small = (text, opts = {}) => new Paragraph({
  spacing: { before: 40, after: 40 },
  alignment: opts.alignment,
  children: [new TextRun({ text, font: "Calibri", size: 18, italics: opts.italics, color: opts.color || GREY })]
});

const bullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { before: 60, after: 60 },
  children: [new TextRun({ text, font: "Calibri", size: 22, color: GREY })]
});

const divider = () => new Paragraph({
  border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 1 } },
  spacing: { before: 120, after: 120 },
  children: [new TextRun("")]
});

// Cell builder
const cell = (content, opts = {}) => new TableCell({
  borders,
  width: { size: opts.width, type: WidthType.DXA },
  shading: opts.shading ? { fill: opts.shading, type: ShadingType.CLEAR } : undefined,
  margins: { top: 120, bottom: 120, left: 160, right: 160 },
  children: Array.isArray(content) ? content : [content]
});

// KPI card table (two-column layout: description left, numbers right)
function kpiCard(num, title, formula, whatItMeans, yourNumbers, benchmark) {
  const leftCell = cell([
    new Paragraph({
      spacing: { before: 40, after: 80 },
      children: [
        new TextRun({ text: `${num}  |  `, font: "Calibri", size: 22, bold: true, color: GOLD }),
        new TextRun({ text: title, font: "Calibri", size: 26, bold: true, color: NAVY })
      ]
    }),
    new Paragraph({
      spacing: { before: 40, after: 100 },
      children: [
        new TextRun({ text: "FORMULA: ", font: "Calibri", size: 18, bold: true, color: NAVY }),
        new TextRun({ text: formula, font: "Calibri", size: 18, italics: true, color: GREY })
      ]
    }),
    new Paragraph({
      spacing: { before: 40, after: 40 },
      children: [new TextRun({ text: "WHAT IT MEANS", font: "Calibri", size: 18, bold: true, color: GOLD })]
    }),
    new Paragraph({
      spacing: { before: 20, after: 40 },
      children: [new TextRun({ text: whatItMeans, font: "Calibri", size: 20, color: GREY })]
    })
  ], { width: 5760, shading: "FFFFFF" });

  const rightChildren = [
    new Paragraph({
      spacing: { before: 40, after: 80 },
      children: [new TextRun({ text: "YOUR NUMBERS", font: "Calibri", size: 18, bold: true, color: NAVY })]
    })
  ];
  yourNumbers.forEach(line => {
    rightChildren.push(new Paragraph({
      spacing: { before: 40, after: 40 },
      children: [new TextRun({ text: line, font: "Calibri", size: 20, color: GREY })]
    }));
  });
  rightChildren.push(new Paragraph({
    spacing: { before: 120, after: 40 },
    children: [new TextRun({ text: "BENCHMARK", font: "Calibri", size: 18, bold: true, color: GOLD })]
  }));
  rightChildren.push(new Paragraph({
    spacing: { before: 20, after: 40 },
    children: [new TextRun({ text: benchmark, font: "Calibri", size: 20, italics: true, color: GREY })]
  }));

  const rightCell = cell(rightChildren, { width: 3600, shading: LIGHT });

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [5760, 3600],
    rows: [new TableRow({ children: [leftCell, rightCell] })]
  });
}

// ============ CONTENT ============
const children = [];

// COVER
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 2400, after: 120 },
  children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Calibri", size: 24, bold: true, color: GOLD, characterSpacing: 80 })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 8 } },
  spacing: { before: 120, after: 480 },
  children: [new TextRun({ text: "", font: "Calibri", size: 2 })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 120, after: 160 },
  children: [new TextRun({ text: "Know Your Numbers", font: "Calibri", size: 72, bold: true, color: NAVY })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 120, after: 240 },
  children: [new TextRun({ text: "The Med Spa Owner's KPI Reference Guide", font: "Calibri", size: 32, italics: true, color: GREY })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 2000, after: 80 },
  children: [new TextRun({ text: "A free resource for independent med spa owners", font: "Calibri", size: 20, italics: true, color: GREY })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 40, after: 120 },
  children: [new TextRun({ text: "theluxoracollective.co", font: "Calibri", size: 20, color: GOLD, bold: true })]
}));

children.push(new Paragraph({ children: [new PageBreak()] }));

// INTRO
children.push(h1("The 10 numbers every profitable med spa tracks."));

children.push(p("This guide gives you the 10 KPIs that separate med spa owners who guess from med spa owners who grow, plus the formula to calculate your Lifetime Value per client.", { size: 24 }));

children.push(p("Fill in your own numbers as you go. These metrics are your dashboard. Once you know them, you stop guessing and start making decisions.", { size: 24 }));

children.push(divider());

children.push(p("Inside this guide:", { size: 22, bold: true, color: NAVY }));
children.push(bullet("The single most important number in your business (start here)"));
children.push(bullet("10 core KPIs with formulas, benchmarks, and fill-in fields"));
children.push(bullet("How these numbers connect to create real profit"));
children.push(bullet("Your next step when you're ready to put it all to work"));

children.push(new Paragraph({ children: [new PageBreak()] }));

// START HERE: LTV
children.push(h1("START HERE: Lifetime Value Per Client (LTV)"));

children.push(p("LTV is the single most important number in your business. It tells you exactly how much one client is worth to you over the full course of your relationship. Without it, every marketing and pricing decision is a guess."));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 240, after: 240 },
  border: { top: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 4 }, bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 4 } },
  children: [new TextRun({ text: "LTV = Average Visit Value  x  Visits Per Year  x  Average Years as a Client", font: "Calibri", size: 24, bold: true, color: NAVY })]
}));

children.push(h3("How to find each input"));

// Input table
children.push(new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [2600, 4360, 2400],
  rows: [
    new TableRow({
      tableHeader: true,
      children: [
        cell(new Paragraph({ children: [new TextRun({ text: "INPUT", font: "Calibri", size: 20, bold: true, color: "FFFFFF" })] }), { width: 2600, shading: NAVY }),
        cell(new Paragraph({ children: [new TextRun({ text: "WHERE TO FIND IT", font: "Calibri", size: 20, bold: true, color: "FFFFFF" })] }), { width: 4360, shading: NAVY }),
        cell(new Paragraph({ children: [new TextRun({ text: "YOUR NUMBER", font: "Calibri", size: 20, bold: true, color: "FFFFFF" })] }), { width: 2400, shading: NAVY })
      ]
    }),
    new TableRow({
      children: [
        cell(new Paragraph({ children: [new TextRun({ text: "Average Visit Value", font: "Calibri", size: 20, bold: true, color: NAVY })] }), { width: 2600 }),
        cell(new Paragraph({ children: [new TextRun({ text: "Total revenue last 90 days divided by total appointments in the same period", font: "Calibri", size: 20, color: GREY })] }), { width: 4360 }),
        cell(new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "$__________", font: "Calibri", size: 22, color: GREY })] }), { width: 2400, shading: LIGHT })
      ]
    }),
    new TableRow({
      children: [
        cell(new Paragraph({ children: [new TextRun({ text: "Visits Per Year", font: "Calibri", size: 20, bold: true, color: NAVY })] }), { width: 2600 }),
        cell(new Paragraph({ children: [new TextRun({ text: "Total appointments last 12 months divided by number of unique clients", font: "Calibri", size: 20, color: GREY })] }), { width: 4360 }),
        cell(new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "__________", font: "Calibri", size: 22, color: GREY })] }), { width: 2400, shading: LIGHT })
      ]
    }),
    new TableRow({
      children: [
        cell(new Paragraph({ children: [new TextRun({ text: "Avg. Years as a Client", font: "Calibri", size: 20, bold: true, color: NAVY })] }), { width: 2600 }),
        cell(new Paragraph({ children: [new TextRun({ text: "Review your client list. How long has your average client been coming to you? Start with 2 years if you are unsure.", font: "Calibri", size: 20, color: GREY })] }), { width: 4360 }),
        cell(new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "__________", font: "Calibri", size: 22, color: GREY })] }), { width: 2400, shading: LIGHT })
      ]
    })
  ]
}));

// Example vs Your LTV side by side
children.push(new Paragraph({ spacing: { before: 240, after: 120 }, children: [new TextRun("")] }));

children.push(new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [4680, 4680],
  rows: [
    new TableRow({
      children: [
        cell([
          new Paragraph({ spacing: { before: 40, after: 80 }, children: [new TextRun({ text: "EXAMPLE", font: "Calibri", size: 20, bold: true, color: GOLD })] }),
          new Paragraph({ spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Average Visit Value: $280", font: "Calibri", size: 22, color: GREY })] }),
          new Paragraph({ spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Visits Per Year: 4", font: "Calibri", size: 22, color: GREY })] }),
          new Paragraph({ spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Avg. Years as Client: 3", font: "Calibri", size: 22, color: GREY })] }),
          new Paragraph({ spacing: { before: 120, after: 40 }, children: [new TextRun({ text: "LTV = $280 x 4 x 3 = $3,360", font: "Calibri", size: 24, bold: true, color: NAVY })] })
        ], { width: 4680, shading: LIGHT }),
        cell([
          new Paragraph({ spacing: { before: 40, after: 80 }, children: [new TextRun({ text: "YOUR LTV", font: "Calibri", size: 20, bold: true, color: GOLD })] }),
          new Paragraph({ spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Average Visit Value: $__________", font: "Calibri", size: 22, color: GREY })] }),
          new Paragraph({ spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Visits Per Year: __________", font: "Calibri", size: 22, color: GREY })] }),
          new Paragraph({ spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "Avg. Years as Client: __________", font: "Calibri", size: 22, color: GREY })] }),
          new Paragraph({ spacing: { before: 120, after: 40 }, children: [new TextRun({ text: "My LTV = $__________", font: "Calibri", size: 24, bold: true, color: NAVY })] })
        ], { width: 4680, shading: "FFFFFF" })
      ]
    })
  ]
}));

children.push(new Paragraph({ spacing: { before: 240, after: 120 }, children: [new TextRun("")] }));

// What your LTV tells you callout
children.push(new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [9360],
  rows: [
    new TableRow({
      children: [
        cell([
          new Paragraph({ spacing: { before: 80, after: 80 }, children: [
            new TextRun({ text: "What your LTV tells you: ", font: "Calibri", size: 22, bold: true, color: NAVY }),
            new TextRun({ text: "If your LTV is $3,360, spending $150 to acquire one new client is not an expense. It is a $3,210 return. Knowing this number gives you permission to invest in growth with confidence instead of hesitation.", font: "Calibri", size: 22, color: GREY })
          ]})
        ], { width: 9360, shading: LIGHT })
      ]
    })
  ]
}));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ==== 10 KPIs ====
children.push(h1("The 10 KPIs Every Med Spa Should Track"));
children.push(p("Each of these numbers tells you something specific. Together, they tell you the truth about your business.", { size: 22, color: GREY }));
children.push(new Paragraph({ spacing: { before: 160 }, children: [new TextRun("")] }));

// 01 CAC
children.push(kpiCard("01", "Customer Acquisition Cost (CAC)",
  "CAC = Total Marketing Spend / New Clients Acquired",
  "What it costs you to bring one new client through the door. Include ad spend, influencer costs, referral incentives, and any staff time tied to outreach. Track this by channel so you know which marketing actually works.",
  ["Marketing spend this month: $__________", "New clients this month: __________", "My CAC: $__________"],
  "$75 to $250 is healthy for most med spas."
));
children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }));

// 02 AOV
children.push(kpiCard("02", "Average Order Value (AOV)",
  "AOV = Total Revenue / Number of Transactions",
  "How much the average client spends per visit. This number goes up when your team recommends add-ons, when you offer packages, and when retail is presented at checkout. One extra $80 product sale per visit adds up fast at scale.",
  ["Revenue last 30 days: $__________", "Total appointments: __________", "My AOV: $__________"],
  "Know your baseline, then set a goal to increase it by 15% within 90 days."
));
children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }));

// 03 LTV
children.push(kpiCard("03", "Client Lifetime Value (LTV)",
  "LTV = Avg Visit Value x Visits/Year x Years as Client",
  "You calculated this above. Come back to it every quarter. Even a small improvement in retention, like keeping clients 1 extra year, can increase LTV by 30 to 50% with zero additional marketing spend.",
  ["My LTV (from above): $__________", "Goal LTV in 12 months: $__________"],
  "Most med spas operating well see LTV between $1,500 and $6,000+."
));

children.push(new Paragraph({ children: [new PageBreak()] }));

// 04 Ratio
children.push(kpiCard("04", "LTV to CAC Ratio",
  "LTV:CAC Ratio = LTV / CAC",
  "Your growth health score. Divide your LTV by your CAC. Below 2x means you are overspending or underretaining. 3x to 5x is healthy. Above 6x means you are likely underinvesting in marketing and leaving revenue behind.",
  ["My LTV: $__________", "My CAC: $__________", "My Ratio: __________x"],
  "3x to 5x = healthy. Above 6x = increase your ad spend."
));
children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }));

// 05 Gross Margin
children.push(kpiCard("05", "Gross Margin Per Treatment",
  "Gross Margin = (Revenue - Direct Costs) / Revenue",
  "How much of each treatment dollar stays after paying for injectables, consumables, and provider labor. Not all services are equal. Run this calculation for every service you offer at least once a year. High-volume, low-margin services can quietly drain profit.",
  ["Service: __________________", "Revenue: $__________", "Direct costs: $__________", "My Margin: __________%"],
  "Strong services run 60% to 80%+ margin. Below 40% needs a hard look."
));
children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }));

// 06 Contribution Margin
children.push(kpiCard("06", "Contribution Margin",
  "Contribution Margin = Revenue - Variable Costs - CAC",
  "Gross margin tells you if a service is profitable. Contribution margin tells you if the client who came in for that service was worth acquiring. Use this before running any discount promotion or Groupon-style offer.",
  ["Service revenue: $__________", "Variable costs: $__________", "CAC: $__________", "Contribution Margin: $__________"],
  "If this number is near zero, the campaign is creating activity but not profit."
));

children.push(new Paragraph({ children: [new PageBreak()] }));

// 07 Break-Even
children.push(kpiCard("07", "Break-Even Treatments Per Month",
  "Break-Even = Fixed Monthly Costs / Contribution Margin Per Treatment",
  "How many treatments you need to perform every month before you earn a single dollar of profit. This number should be posted somewhere visible. If you are below it, everything else is noise until you fix it.",
  ["Fixed costs/month: $__________", "Avg contribution margin: $__________", "Break-even target: __________"],
  "Recalculate any time you add a new provider, equipment, or space."
));
children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }));

// 08 RPP
children.push(kpiCard("08", "Revenue Per Patient (RPP)",
  "RPP = Total Revenue / Total Unique Clients",
  "Measures the depth of client relationships, not just headcount. A low RPP means your clients are transactional. A high RPP means they trust you, return often, and invest in multiple services. This number improves when providers present comprehensive care options.",
  ["Revenue last 12 months: $__________", "Unique clients: __________", "My RPP: $__________"],
  "Track this quarterly. Rising RPP = growing client trust and spend."
));
children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }));

// 09 Utilization
children.push(kpiCard("09", "Provider Utilization Rate",
  "Utilization = Booked Treatment Hours / Available Treatment Hours",
  "How efficiently your providers convert their time into revenue. Gaps, no-shows, and admin during prime hours all drag this down silently. Going from 65% to 80% utilization on the same provider can add tens of thousands of dollars annually with no new overhead.",
  ["Booked hours this week: __________", "Available hours this week: __________", "My Rate: __________%"],
  "Target 75% to 85%. Below 70% is a profit leak. Require deposits."
));

children.push(new Paragraph({ children: [new PageBreak()] }));

// 10 Payback
children.push(kpiCard("10", "Marketing Payback Period",
  "Payback Period = CAC / Monthly Gross Profit Per Client",
  "How many months to recover what you spent to acquire a client. A membership client paying monthly shortens this dramatically. If any channel has a payback period over 12 months, that channel deserves a serious review.",
  ["My CAC: $__________", "Monthly gross profit/client: $__________", "Payback Period: __________ months"],
  "Under 6 months is strong. Membership programs are the fastest way to shorten this."
));

children.push(new Paragraph({ spacing: { before: 320 }, children: [new TextRun("")] }));

// How these numbers connect
children.push(h2("How These Numbers Connect"));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 120, after: 240 },
  border: { top: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 4 }, bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 4 } },
  children: [new TextRun({ text: "Marketing Spend  >  CAC  >  LTV  >  Margin  >  Cash Flow", font: "Calibri", size: 24, bold: true, color: NAVY })]
}));

children.push(bullet("Marketing spend drives your CAC. CAC relative to LTV determines whether growth is sustainable."));
children.push(bullet("Gross margin per treatment determines how much of each dollar of LTV actually survives to profit."));
children.push(bullet("Utilization rate determines how efficiently your capacity converts into revenue."));
children.push(bullet("Break-even analysis grounds all of it in your real fixed cost structure."));
children.push(bullet("Owners who track these monthly stop making decisions based on how busy the schedule feels. They make decisions based on what the data says."));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ==== PROMOTIONAL CLOSE ====
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 240, after: 80 },
  children: [new TextRun({ text: "NOW WHAT?", font: "Calibri", size: 22, bold: true, color: GOLD, characterSpacing: 80 })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 80, after: 80 },
  children: [new TextRun({ text: "You know the numbers.", font: "Calibri", size: 56, bold: true, color: NAVY })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 40, after: 240 },
  children: [new TextRun({ text: "The question is what you do with them.", font: "Calibri", size: 32, italics: true, color: GREY })]
}));

children.push(divider());

children.push(p("Here's what most med spa owners discover when they fill in these fields honestly.", { size: 24, bold: true, color: NAVY }));
children.push(p("Their LTV is higher than they thought. Their utilization rate is lower. Their CAC works on paper but their payback period is dragging cash flow. Their AOV has been flat for two years. And there is no membership program converting walk-ins into predictable monthly revenue."));

children.push(p("That is not a business problem. It is a systems problem. And systems are fixable."));

children.push(new Paragraph({ spacing: { before: 240 }, children: [new TextRun("")] }));

// The Luxora Collective block
children.push(new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [9360],
  rows: [
    new TableRow({
      children: [
        cell([
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 120, after: 80 },
            children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Calibri", size: 20, bold: true, color: GOLD, characterSpacing: 80 })]
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 80, after: 160 },
            children: [new TextRun({ text: "We turn KPIs into cash flow.", font: "Calibri", size: 36, bold: true, color: NAVY })]
          }),
          new Paragraph({
            spacing: { before: 80, after: 120 },
            children: [new TextRun({ text: "We are a premium revenue growth partner built specifically for independent med spa owners doing $500K to $2M. We do not run funnels for you and disappear. We work from the inside out, knowledge transfer at every step, so you end the engagement more capable, confident, and in control of your business, not dependent on us.", font: "Calibri", size: 22, color: GREY })]
          }),
          new Paragraph({ spacing: { before: 120, after: 80 }, children: [new TextRun({ text: "Here is how it works.", font: "Calibri", size: 22, bold: true, color: NAVY })] })
        ], { width: 9360, shading: LIGHT })
      ]
    })
  ]
}));

children.push(new Paragraph({ spacing: { before: 240 }, children: [new TextRun("")] }));

// Step 1
children.push(new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [1200, 8160],
  rows: [
    new TableRow({
      children: [
        cell(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 120, after: 120 }, children: [new TextRun({ text: "01", font: "Calibri", size: 48, bold: true, color: "FFFFFF" })] }), { width: 1200, shading: NAVY }),
        cell([
          new Paragraph({ spacing: { before: 80, after: 40 }, children: [new TextRun({ text: "Revenue Leak Audit", font: "Calibri", size: 26, bold: true, color: NAVY })] }),
          new Paragraph({ spacing: { before: 40, after: 80 }, children: [new TextRun({ text: "We find the revenue you are already earning but losing. Undertrained front desks, unconverted consults, stagnant clients, missing memberships, weak packages. You get a clear number in dollars for what is leaking and exactly where.", font: "Calibri", size: 22, color: GREY })] })
        ], { width: 8160 })
      ]
    })
  ]
}));

children.push(new Paragraph({ spacing: { before: 120 }, children: [new TextRun("")] }));

// Step 2
children.push(new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [1200, 8160],
  rows: [
    new TableRow({
